502	```c
503	#include <lvgl/lvgl.h>
504	#include <nuttx/nuttx.h>
505	
506	/* ── 传感器数据标签 ── */
507	static lv_obj_t *accel_label;
508	static lv_obj_t *mag_label;
509	static lv_obj_t *light_label;
510	
511	/* ── 实时图表 ── */
512	static lv_obj_t *chart;
513	static lv_chart_series_t *accel_ser;
514	
515	/* ── 事件回调 ── */
516	static void btn_event_cb(lv_event_t *e)
517	{
518	  lv_event_code_t code = lv_event_get_code(e);
519	  if (code == LV_EVENT_CLICKED)
520	    {
521	      /* 切换到实验界面 */
522	    }
523	}
524	
525	/* ── 定时器回调：更新传感器数据 ── */
526	static void update_sensor_cb(lv_timer_t *timer)
527	{
528	  /* 从 uORB 读取最新数据 */
529	  struct sensor_accel accel;
530	  struct sensor_mag mag;
531	  struct sensor_light light;
532	
533	  /* 更新标签 */
534	  lv_label_set_text_fmt(accel_label, "Accel: %.2f m/s²",
535	                        sqrtf(accel.x*accel.x + accel.y*accel.y + accel.z*accel.z));
536	  lv_label_set_text_fmt(mag_label, "Mag: %.1f µT",
537	                        sqrtf(mag.x*mag.x + mag.y*mag.y + mag.z*mag.z));
538	  lv_label_set_text_fmt(light_label, "Light: %.1f lux", light.light);
539	
540	  /* 更新图表 */
541	  lv_chart_set_next(chart, accel_ser, accel.x * 100);
542	}
543	
544	/* ── 主界面构建 ── */
545	void phywear_main_ui(void)
546	{
547	  lv_obj_t *scr = lv_screen_active();
548	  lv_obj_set_style_bg_color(scr, lv_color_hex(0x000000), LV_PART_MAIN);
549	
550	  /* 标题 */
551	  lv_obj_t *title = lv_label_create(scr);
552	  lv_label_set_text(title, "PhyWear");
553	  lv_obj_set_style_text_color(title, lv_color_hex(0x00FF00), 0);
554	  lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 10);
555	
556	  /* 传感器数据卡片 */
557	  accel_label = lv_label_create(scr);
558	  lv_obj_align(accel_label, LV_ALIGN_TOP_LEFT, 10, 50);
559	
560	  mag_label = lv_label_create(scr);
561	  lv_obj_align(mag_label, LV_ALIGN_TOP_LEFT, 10, 80);
562	
563	  light_label = lv_label_create(scr);
564	  lv_obj_align(light_label, LV_ALIGN_TOP_LEFT, 10, 110);
565	
566	  /* 实时波形图表 */
567	  chart = lv_chart_create(scr);
568	  lv_obj_set_size(chart, 360, 120);
569	  lv_obj_align(chart, LV_ALIGN_CENTER, 0, 30);
570	  lv_chart_set_type(chart, LV_CHART_TYPE_LINE);
571	  lv_chart_set_point_count(chart, 100);
572	  lv_chart_set_range(chart, LV_CHART_AXIS_PRIMARY_Y, -200, 200);
573	  accel_ser = lv_chart_add_series(chart, lv_color_hex(0xFF0000));
574	
575	  /* 功能按钮 */
576	  lv_obj_t *btn = lv_button_create(scr);
577	  lv_obj_set_size(btn, 120, 40);
578	  lv_obj_align(btn, LV_ALIGN_BOTTOM_MID, 0, -20);
579	  lv_obj_t *btn_label = lv_label_create(btn);
580	  lv_label_set_text(btn_label, "Experiment");
581	  lv_obj_add_event_cb(btn, btn_event_cb, LV_EVENT_CLICKED, NULL);
582	
583	  /* 定时器：每 50ms 更新传感器数据 */
584	  lv_timer_create(update_sensor_cb, 50, NULL);
585	}
586	
587	/* ── 入口函数 ── */
588	int main(int argc, char *argv[])
589	{
590	  lv_init();
591	
592	  struct lv_nuttx_dsc_s info;
593	  struct lv_nuttx_result_s result;
594	  lv_nuttx_dsc_init(&info);
595	  info.input_path = "/dev/input0";    /* FT6146 触控 */
596	  lv_nuttx_init(&info, &result);
597	
598	  phywear_main_ui();
599	
600	  while (1)
601	    {
602	      uint32_t idle = lv_timer_handler();
603	      usleep(idle * 1000);
604	    }
605	
606	  return 0;
607	}
